<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {useResearchData} from '../hooks/useResearch';import RunSummary from '../components/RunSummary.vue';import GroupProfiles from '../components/GroupProfiles.vue';import CompositionMatrix from '../components/CompositionMatrix.vue';import PermutationPlot from '../components/PermutationPlot.vue';import DataTable from '../components/common/DataTable.vue';import StatusBadge from '../components/common/StatusBadge.vue';import Notice from '../components/common/Notice.vue';import {number} from '../utils/format';const s=useResearchData(true),route=useRoute(),id=ref(Number(route.query.run)||0);const run=computed(()=>id.value?s.runs.find(x=>x.id===id.value):s.runs[0]);</script><template><div class="page results-page"><div class="page-title"><div><p class="eyebrow">GROUP GEOMETRY & GLOBAL EVIDENCE / 04</p><h1>组间组成证据<span>差异留在CLR几何里，不替代工艺解释。</span></h1></div><RouterLink class="outline" :to="'/notes'+(run?'?run='+run.id:'')">记录复配补样 →</RouterLink></div><Notice :message="s.error" @retry="s.refresh"/><div class="run-picker"><label>研究档案<select aria-label="研究档案" :value="run?.id||''" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="x in s.runs" :key="x.id" :value="x.id">#{{x.id}} / {{x.name}} / {{x.status}}</option></select></label><StatusBadge v-if="run" :status="run.status"/></div><template v-if="run?.status==='completed'"><RunSummary :run="run"/><div class="result-grid"><GroupProfiles :result="run.result"/><aside><PermutationPlot :result="run.result"/><div class="reading-note"><h2>先读解释边界</h2><p>{{run.result.assumptions}}</p><p>{{run.result.interpretation}}</p></div></aside></div><div class="section-heading"><h2>平方和与自由度</h2><span>CLR欧氏空间 / R²上尾置换</span></div><DataTable :head="['项','平方和','自由度','统计口径']"><tr><td>组间</td><td>{{number(run.result.statistics.SSB,6)}}</td><td>{{run.result.statistics.df_between}}</td><td>R² {{number(run.result.statistics.R2,5)}}</td></tr><tr><td>组内</td><td>{{number(run.result.statistics.SSW,6)}}</td><td>{{run.result.statistics.df_within}}</td><td>pseudo-F {{run.result.statistics.F_status==='unbounded'?'无界':run.result.statistics.F_status==='numerical_overflow'?'数值超范围':number(run.result.statistics.F!,5)}}</td></tr><tr><td>总计</td><td>{{number(run.result.statistics.SST,6)}}</td><td>{{run.result.statistics.n-1}}</td><td>p {{number(run.result.statistics.p,4)}} / {{run.permutations}}置换</td></tr></DataTable><div class="section-heading"><h2>替换前后与CLR矩阵</h2><span>全部{{run.result.transformed.length}}样本 / 可切换原值、闭合、替换、CLR</span></div><CompositionMatrix :components="run.result.components" :samples="run.result.transformed.map(x=>x.sample)" :transformed="run.result.transformed"/><p class="replacement-note">{{run.result.replacement_note}} δ={{run.delta}}；不是自动估计检出限。</p><div class="section-heading"><h2>组内距离描述</h2><span>未正式检验离散度同质</span></div><DataTable :head="['组','n','平均到CLR质心距离','最大到CLR质心距离']"><tr v-for="g in run.result.statistics.groups" :key="g.group"><td>{{g.group}}</td><td>{{g.n}}</td><td>{{number(g.mean_distance_to_centroid,5)}}</td><td>{{number(g.max_distance_to_centroid,5)}}</td></tr></DataTable><p class="fingerprint">{{run.result.algorithm_version}} / INPUT SHA256 {{run.result.input_hash}}</p></template><div v-else-if="run" class="pending"><h2>{{run.status==='failed'?'研究未完成':'独立worker正在变换与置换'}}</h2><p>{{run.error||'本页每2秒更新，所有null R²保留。'}}</p></div><p v-else class="empty">正在读取研究快照；可先从配置建立研究。</p></div></template>
